from ninja import Router
from ninja.security import HttpBearer
from ninja.errors import HttpError
from django.core.cache import cache

tenant_cache_router = Router(auth=HttpBearer())

@tenant_cache_router.delete("/cache/tenant-plans/{tenant_id}")
def purge_tenant_plan_cache(request, tenant_id: int):
    # Verify the caller is an administrator of the target tenant
    if request.auth.tenant_id != tenant_id and not request.auth.is_staff:
        raise HttpError(403, "Cannot purge cache for another tenant")

    cache_key = f"tenant_pricing_tiers:{tenant_id}"
    deleted = cache.delete(cache_key)
    return {"tenant_id": tenant_id, "cache_key": cache_key, "deleted": bool(deleted)}
